package org.apache.commons.math.fraction;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.exception.MathIllegalArgumentException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.ZeroException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.ArithmeticUtils;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class BigFraction_doubleValue_TriageGen4Test {

    private static final double EPSILON = 1e-15;

    @Test
    public void testDoubleValue_SimpleInteger() {
        BigFraction fraction = new BigFraction(1, 2);
        assertEquals(0.5, fraction.doubleValue(), EPSILON);
    }

    @Test
    public void testDoubleValue_LargeNumerator() {
        // Test handling of large numbers that fit in double
        BigFraction fraction = new BigFraction(new BigInteger("1000000000000000"), new BigInteger("1"));
        assertEquals(1000000000000000.0, fraction.doubleValue(), EPSILON);
    }

    @Test
    public void testDoubleValue_LargeDenominator() {
        BigFraction fraction = new BigFraction(new BigInteger("1"), new BigInteger("1000000000000000"));
        assertEquals(1e-15, fraction.doubleValue(), 1e-16);
    }

    @Test
    public void testDoubleValue_ZeroNumerator() {
        BigFraction fraction = new BigFraction(0, 5);
        assertEquals(0.0, fraction.doubleValue(), EPSILON);
    }

    @Test
    public void testDoubleValue_NegativeValues() {
        BigFraction fraction1 = new BigFraction(-1, 2);
        assertEquals(-0.5, fraction1.doubleValue(), EPSILON);

        BigFraction fraction2 = new BigFraction(1, -2);
        assertEquals(-0.5, fraction2.doubleValue(), EPSILON);

        BigFraction fraction3 = new BigFraction(-1, -2);
        assertEquals(0.5, fraction3.doubleValue(), EPSILON);
    }

    @Test
    public void testDoubleValue_OverflowToInfinity() {
        // Create a fraction that exceeds Double.MAX_VALUE
        BigInteger hugeNum = new BigInteger("1" + "0".repeat(400)); 
        BigInteger den = BigInteger.ONE;
        BigFraction fraction = new BigFraction(hugeNum, den);

        // result should be Double.POSITIVE_INFINITY
        assertEquals(Double.POSITIVE_INFINITY, fraction.doubleValue(), 0.0);
    }

    @Test
    public void testDoubleValue_UnderflowToZero() {
        // Create a fraction that is smaller than Double.MIN_VALUE
        BigInteger hugeDen = new BigInteger("1" + "0".repeat(400));
        BigInteger num = BigInteger.ONE;
        BigFraction fraction = new BigFraction(num, hugeDen);

        // result should be 0.0
        assertEquals(0.0, fraction.doubleValue(), 0.0);
    }

    @Test
    public void testDoubleValue_DivisionByZero() {
        // Note: BigFraction constructor usually prevents zero denominator, 
        // but checking if the math logic handles it if it were possible.
        // In Apache Commons Math, BigFraction(num, 0) throws MathIllegalArgumentException.
        try {
            new BigFraction(1, 0);
        } catch (MathIllegalArgumentException e) {
            // Expected
        }
    }

    @Test
    public void testDoubleValue_Precision() {
        // Test decimal precision
        BigFraction fraction = new BigFraction(new BigInteger("1"), new BigInteger("3"));
        assertEquals(0.3333333333333333, fraction.doubleValue(), 1e-15);
    }

    @Test
    public void testDoubleValue_FromDoubleConstructor() {
        double val = 0.123456789;
        BigFraction fraction = new BigFraction(val);
        assertEquals(val, fraction.doubleValue(), EPSILON);
    }
}
